<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Tetris</title>
<style>
  :root {
    --cell: 28px;
    --bg: #14161c;
    --panel: #1e2129;
    --line: #2a2e38;
    --text: #e8eaf0;
    --muted: #9aa0ad;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--bg);
    color: var(--text);
    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  }
  .game {
    display: flex;
    gap: 20px;
    align-items: flex-start;
    padding: 20px;
  }
  .board-wrap { position: relative; }
  .board {
    display: grid;
    grid-template-columns: repeat(10, var(--cell));
    grid-template-rows: repeat(20, var(--cell));
    gap: 1px;
    padding: 1px;
    background: var(--line);
    border: 2px solid var(--line);
  }
  .cell { background: var(--panel); }
  .cell[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18); }
  .overlay {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(0,0,0,0.6);
    font-size: 24px;
    font-weight: 600;
  }
  .side {
    display: flex;
    flex-direction: column;
    gap: 14px;
    min-width: 140px;
  }
  .box {
    background: var(--panel);
    border: 1px solid var(--line);
    padding: 10px 12px;
  }
  .label {
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--muted);
  }
  .value { font-size: 22px; font-weight: 600; margin-top: 2px; }
  .next-list { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }
  .mini {
    display: grid;
    grid-template-columns: repeat(4, 16px);
    grid-template-rows: repeat(2, 16px);
    gap: 1px;
  }
  .mini-cell { background: transparent; }
  button {
    font: inherit;
    color: var(--text);
    background: var(--panel);
    border: 1px solid var(--line);
    padding: 8px 12px;
    cursor: pointer;
  }
  button:hover { border-color: var(--muted); }
  .help { font-size: 12px; color: var(--muted); line-height: 1.6; }
  .p-I { background: #22c7e0; }
  .p-O { background: #f2c511; }
  .p-T { background: #9b4dca; }
  .p-S { background: #3cb44b; }
  .p-Z { background: #e6194b; }
  .p-J { background: #2f6fdf; }
  .p-L { background: #f58231; }
</style>
</head>
<body>
<div class="game">
  <div class="board-wrap">
    <div class="board" data-testid="board" id="board"></div>
    <div class="overlay" id="overlay" hidden>Game over</div>
  </div>
  <div class="side">
    <div class="box">
      <div class="label">Score</div>
      <div class="value" data-testid="score" id="score">0</div>
    </div>
    <div class="box">
      <div class="label">Level</div>
      <div class="value" data-testid="level" id="level">1</div>
    </div>
    <div class="box">
      <div class="label">Lines</div>
      <div class="value" data-testid="lines" id="lines">0</div>
    </div>
    <div class="box">
      <div class="label">Next</div>
      <div class="next-list" id="next"></div>
    </div>
    <button type="button" id="new-game">New game</button>
    <div class="help">
      ← → move<br>
      ↓ soft drop<br>
      Space hard drop<br>
      ↑ rotate
    </div>
  </div>
</div>

<script>
(function () {
  "use strict";

  var ROWS = 20;
  var COLS = 10;
  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
  var PREVIEW = 3;
  var GRAVITY_MS = 1000;
  var LOCK_DELAY_TICKS = 2;   // gravity steps a piece may spend unable to fall
  var MAX_LOCK_RESETS = 3;    // times per piece a sideways move restarts the delay

  // Points for rows cleared at once, times the level. Clearing rows together
  // must always beat clearing the same rows one at a time.
  var CLEAR_POINTS = [0, 100, 300, 500, 800];
  var SOFT_DROP_POINTS = 1;   // per cell moved down by soft drop
  var HARD_DROP_POINTS = 2;   // per cell dropped by hard drop

  // Each shape is a square matrix; spawn puts its filled cells in rows 0-1.
  var SHAPES = {
    I: { m: ["....", "IIII", "....", "...."], row: -1, col: 3 },
    O: { m: ["OO", "OO"], row: 0, col: 4 },
    T: { m: [".T.", "TTT", "..."], row: 0, col: 3 },
    S: { m: [".SS", "SS.", "..."], row: 0, col: 3 },
    Z: { m: ["ZZ.", ".ZZ", "..."], row: 0, col: 3 },
    J: { m: ["J..", "JJJ", "..."], row: 0, col: 3 },
    L: { m: ["..L", "LLL", "..."], row: 0, col: 3 }
  };

  // ---- State ----
  var board;        // board[row][col] = "" or piece letter
  var current;      // { type, matrix, row, col, lockTicks, lockResets } or null
  var next;         // upcoming piece letters, soonest first
  var scripted;     // true while `next` comes from a test-supplied queue
  var bag = [];
  var score, level, lines, status;
  var timer = null;

  function emptyBoard() {
    var b = [];
    for (var r = 0; r < ROWS; r++) {
      var row = [];
      for (var c = 0; c < COLS; c++) row.push("");
      b.push(row);
    }
    return b;
  }

  function randomType() {
    if (bag.length === 0) {
      bag = TYPES.slice();
      for (var i = bag.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
      }
    }
    return bag.pop();
  }

  function fillPreview() {
    if (scripted) return;
    while (next.length < PREVIEW) next.push(randomType());
  }

  function shapeCells(matrix, row, col) {
    var cells = [];
    for (var r = 0; r < matrix.length; r++) {
      for (var c = 0; c < matrix[r].length; c++) {
        if (matrix[r][c] !== ".") cells.push([row + r, col + c]);
      }
    }
    return cells;
  }

  function fits(matrix, row, col) {
    var cells = shapeCells(matrix, row, col);
    for (var i = 0; i < cells.length; i++) {
      var r = cells[i][0], c = cells[i][1];
      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
      if (board[r][c] !== "") return false;
    }
    return true;
  }

  function spawn() {
    if (next.length === 0) scripted = false;
    fillPreview();
    var type = next.shift();
    fillPreview();
    var s = SHAPES[type];
    var piece = {
      type: type, matrix: s.m.slice(), row: s.row, col: s.col,
      lockTicks: 0,   // consecutive gravity steps spent unable to fall
      lockResets: 0   // lifetime count of lock-delay restarts
    };
    if (!fits(piece.matrix, piece.row, piece.col)) {
      current = null;
      status = "over";
      stopTimer();
      return;
    }
    current = piece;
  }

  function lock() {
    var cells = shapeCells(current.matrix, current.row, current.col);
    for (var i = 0; i < cells.length; i++) {
      board[cells[i][0]][cells[i][1]] = current.type;
    }
    current = null;
    clearLines();
    spawn();
  }

  // Removes every full row; rows above drop down.
  function clearLines() {
    var kept = board.filter(function (row) {
      return row.some(function (v) { return v === ""; });
    });
    var cleared = ROWS - kept.length;
    if (cleared === 0) return;
    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
    board = kept;
    lines += cleared;
    score += CLEAR_POINTS[Math.min(cleared, 4)] * level;
  }

  function tryMove(dr, dc) {
    if (!current) return false;
    if (!fits(current.matrix, current.row + dr, current.col + dc)) return false;
    current.row += dr;
    current.col += dc;
    return true;
  }

  // The single gravity step, used by the real timer, tick() and soft drop.
  // A step that cannot move the piece down counts one tick of lock delay.
  // Returns true if the piece moved down.
  function gravityStep() {
    if (status !== "running" || !current) return false;
    if (tryMove(1, 0)) {
      current.lockTicks = 0;
      return true;
    }
    current.lockTicks++;
    if (current.lockTicks >= LOCK_DELAY_TICKS) lock();
    return false;
  }

  function softDrop() {
    if (gravityStep()) score += SOFT_DROP_POINTS;
  }

  // Left/right. A move made while the lock delay is running restarts it,
  // up to MAX_LOCK_RESETS times per piece.
  function shift(dc) {
    var resting = current.lockTicks > 0;
    if (!tryMove(0, dc)) return;
    if (resting && current.lockResets < MAX_LOCK_RESETS) {
      current.lockResets++;
      current.lockTicks = 0;
    }
  }

  // Clockwise rotation. Tries the rotated shape in place, then shifted
  // sideways; if none fit, the piece is left unchanged.
  function rotateCW() {
    if (!current) return;
    var m = current.matrix;
    var n = m.length;
    var rotated = [];
    for (var r = 0; r < n; r++) {
      var line = "";
      for (var c = 0; c < n; c++) line += m[n - 1 - c][r];
      rotated.push(line);
    }
    var kicks = [0, -1, 1, -2, 2];
    for (var i = 0; i < kicks.length; i++) {
      var nc = current.col + kicks[i];
      if (fits(rotated, current.row, nc)) {
        current.matrix = rotated;
        current.col = nc;
        return;
      }
    }
  }

  // Hard drop skips the lock delay.
  function hardDrop() {
    if (!current) return;
    while (tryMove(1, 0)) score += HARD_DROP_POINTS;
    lock();
  }

  function applyInput(action) {
    if (status !== "running" || !current) return;
    switch (action) {
      case "left": shift(-1); break;
      case "right": shift(1); break;
      case "softDrop": softDrop(); break;
      case "hardDrop": hardDrop(); break;
      case "rotateCW":
      case "rotate": rotateCW(); break;
    }
  }

  // ---- Timer ----
  function stopTimer() {
    if (timer !== null) { clearInterval(timer); timer = null; }
  }

  function startTimer() {
    stopTimer();
    timer = setInterval(function () {
      gravityStep();
      render();
    }, GRAVITY_MS);
  }

  // ---- Rendering (synchronous) ----
  var boardEl = document.getElementById("board");
  var nextEl = document.getElementById("next");
  var overlayEl = document.getElementById("overlay");
  var scoreEl = document.getElementById("score");
  var levelEl = document.getElementById("level");
  var linesEl = document.getElementById("lines");
  var cellEls = [];

  (function buildBoard() {
    for (var r = 0; r < ROWS; r++) {
      cellEls.push([]);
      for (var c = 0; c < COLS; c++) {
        var el = document.createElement("div");
        el.className = "cell";
        el.setAttribute("data-testid", "cell");
        el.setAttribute("data-row", String(r));
        el.setAttribute("data-col", String(c));
        el.setAttribute("data-filled", "false");
        el.setAttribute("data-piece", "");
        boardEl.appendChild(el);
        cellEls[r].push(el);
      }
    }
  })();

  function paintCell(el, piece) {
    el.className = piece ? "cell p-" + piece : "cell";
    el.setAttribute("data-filled", piece ? "true" : "false");
    el.setAttribute("data-piece", piece);
  }

  function renderNext() {
    nextEl.textContent = "";
    for (var i = 0; i < Math.min(next.length, PREVIEW); i++) {
      var type = next[i];
      var m = SHAPES[type].m;
      var offset = type === "I" ? 1 : 0; // I's filled row is row 1 of its matrix
      var mini = document.createElement("div");
      mini.className = "mini";
      for (var r = 0; r < 2; r++) {
        for (var c = 0; c < 4; c++) {
          var ch = m[r + offset] && m[r + offset][c];
          var cell = document.createElement("div");
          cell.className = ch && ch !== "." ? "mini-cell p-" + type : "mini-cell";
          mini.appendChild(cell);
        }
      }
      nextEl.appendChild(mini);
    }
  }

  function render() {
    var view = board.map(function (row) { return row.slice(); });
    if (current) {
      var cells = shapeCells(current.matrix, current.row, current.col);
      for (var i = 0; i < cells.length; i++) {
        view[cells[i][0]][cells[i][1]] = current.type;
      }
    }
    for (var r = 0; r < ROWS; r++) {
      for (var c = 0; c < COLS; c++) paintCell(cellEls[r][c], view[r][c]);
    }
    scoreEl.textContent = String(score);
    levelEl.textContent = String(level);
    linesEl.textContent = String(lines);
    overlayEl.hidden = status !== "over";
    renderNext();
  }

  // ---- Game control ----
  function validTypes(queue) {
    if (!Array.isArray(queue)) return [];
    return queue.filter(function (t) { return SHAPES.hasOwnProperty(t); });
  }

  function newGame(queue) {
    board = emptyBoard();
    score = 0;
    level = 1;
    lines = 0;
    status = "running";
    current = null;
    bag = [];
    if (Array.isArray(queue)) {
      next = validTypes(queue);
      scripted = true;
    } else {
      next = [];
      scripted = false;
    }
    spawn();
    startTimer();
    render();
  }

  function setQueue(queue) {
    next = validTypes(queue);
    scripted = true;
    render();
  }

  function setBoard(rows) {
    var b = emptyBoard();
    for (var r = 0; r < ROWS; r++) {
      var line = (rows && rows[r]) || "";
      for (var c = 0; c < COLS; c++) {
        var ch = line.charAt(c);
        b[r][c] = SHAPES.hasOwnProperty(ch) ? ch : "";
      }
    }
    board = b;
    render();
  }

  function getBoard() {
    return board.map(function (row) {
      return row.map(function (v) { return v || "."; }).join("");
    });
  }

  function getState() {
    var cur = null;
    if (current) {
      var cells = shapeCells(current.matrix, current.row, current.col);
      cells.sort(function (a, b) { return a[0] - b[0] || a[1] - b[1]; });
      cur = { type: current.type, cells: cells };
    }
    return {
      current: cur,
      next: next.slice(),
      score: score,
      level: level,
      lines: lines,
      status: status
    };
  }

  function tick(n) {
    var steps = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
    for (var i = 0; i < steps; i++) gravityStep();
    render();
  }

  window.__tetris = {
    newGame: newGame,
    setQueue: setQueue,
    setBoard: setBoard,
    tick: tick,
    input: function (action) { applyInput(action); render(); },
    getBoard: getBoard,
    getState: getState
  };

  // ---- Keyboard ----
  var KEYS = {
    ArrowLeft: "left",
    ArrowRight: "right",
    ArrowDown: "softDrop",
    " ": "hardDrop",
    ArrowUp: "rotateCW"
  };

  document.addEventListener("keydown", function (e) {
    var action = KEYS[e.key];
    if (!action) return;
    e.preventDefault();
    window.__tetris.input(action);
  });

  document.getElementById("new-game").addEventListener("click", function (e) {
    e.currentTarget.blur();
    newGame();
  });

  newGame();
})();
</script>
</body>
</html>

